import { z } from "zod";

/**
 * Timeline summary schemas — see `@a-company/atelier-types/timeline.ts` for
 * semantics (derived overview of clip placements, regenerated by writers,
 * tolerated as missing/stale by readers).
 */

export const TimelineClipSchema = z.object({
  layerId: z.string().min(1, "TimelineClip.layerId is required"),
  startFrame: z.number().int().min(0, "startFrame must be a non-negative integer"),
  endFrame: z.number().int().min(0, "endFrame must be a non-negative integer"),
  source: z.string().min(1, "TimelineClip.source is required"),
});

export const TimelineTrackSchema = z.object({
  id: z.string().min(1, "TimelineTrack.id is required"),
  kind: z.enum(["video", "audio"]),
  clips: z.array(TimelineClipSchema),
});

export const TimelineSchema = z.object({
  fps: z.number().int().positive("Timeline.fps must be a positive integer"),
  totalFrames: z.number().int().min(0, "Timeline.totalFrames must be a non-negative integer"),
  tracks: z.array(TimelineTrackSchema),
});
